theme_template:
/* =====================================================
   PAGE BACKGROUND
===================================================== */

.no-breadcrumbs {
	background: var(--secondary) 100%;
}

/* =====================================================
   NAVBAR
===================================================== */
.navbar {
	background: linear-gradient(
	    90deg,
	    var(--primary) 0%,
	    var(--accent) 45%,
	    var(--secondary) 100%
    ) !important;
}

.navbar .awesomplete .form-control {
	border: 1px solid var(--accent) !important;
	border-radius: 6px;
}

.navbar .awesomplete .form-control:hover {
	box-shadow: 0 6px 20px rgba(0, 0, 0, 0.1) !important;
}

.nav.navbar-nav a {
	color: #000 !important;
	font-weight: 600 !important;
}


/* =====================================================
   PAGE HEAD & CONTAINER
===================================================== */
/* .page-head,
.page-container {
	background: var(--secondary) !important;
} */



/* =====================================================
   SIDEBAR
===================================================== */
.body-sidebar {
	background: var(--primary) !important;
}

.layout-side-section {
	background: var(--secondary) !important;
       border-radius: 0px !important;
}

.workspace-sidebar {
	background: #fff !important;
	border-radius: 6px !important;
	border-right: 1px solid #eee !important;
}

.workspace-sidebar .sidebar-item {
	padding: 10px 14px !important;
	margin-bottom: 6px !important;
	border-radius: 6px !important;
	font-weight: 600 !important;
	transition: 0.2s ease all;
}

.workspace-sidebar .sidebar-item:hover {
	background: rgba(125, 42, 232, 0.06) !important;
}

.workspace-sidebar .sidebar-item.selected {
	background: var(--primary) !important;
	color: #fff !important;
}


/* =====================================================
   SIDEBAR SELECTED ITEM
===================================================== */
.desk-sidebar-item.standard-sidebar-item.selected {
	background: linear-gradient(
		90deg,
		var(--secondary),
		var(--primary)
	) !important;
	font-weight: 700 !important;
}


/* =====================================================
   WORKSPACE BODY & TITLE
===================================================== */
.workspace-body {
	background: var(--primary) !important;
	padding-top: 10px;
}

.workspace-title .title-text {
	font-size: 26px !important;
	font-weight: 600 !important;
	color: #333 !important;
}


/* =====================================================
   WIDGET GRID & CARDS
===================================================== */
.widget-group {
	display: grid !important;
	grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)) !important;
	gap: 18px !important;
}

.widget {
	background: var(--secondary) !important;
	border: 1px solid var(--primary) !important;
	border-radius: 6px !important;
	padding: 18px !important;
	box-shadow: 0 4px 14px rgba(0, 0, 0, 0.06) !important;
	transition: 0.25s ease all;
}

.widget:hover {
	transform: translateY(-3px);
	box-shadow: 0 6px 20px rgba(0, 0, 0, 0.1) !important;
}

.widget.spacer {
	display: none !important;
}

.widget .widget-head,
.widget .widget-title .ellipsis {
	font-size: 16px !important;
	font-weight: 600 !important;
	color: var(--primary-text-color-light) !important;
}


/* =====================================================
   SHORTCUT WIDGET
===================================================== */
.shortcut-widget-box {
	background: var(--secondary) !important;
	border-radius: 6px !important;
	padding: 14px !important;
	font-size: 15px !important;
	box-shadow: 0 4px 14px rgba(0, 0, 0, 0.06) !important;
}


/* =====================================================
   WIDGET LINKS
===================================================== */
.widget-body a {
	color: #555 !important;
}

.widget-body a:hover {
	color: var(--secondary-text-color-light) !important;
}

.widget-body .link-item {
	position: relative;
	display: flex;
	align-items: center;
	padding-left: 20px !important;
	margin-bottom: 6px;
}

.widget-body .link-item::before {
	content: "•";
	position: absolute;
	left: 0;
	top: 4px;
	font-size: 18px;
	color: var(--secondary-text-color-light);
}


/* =====================================================
   BUTTONS
===================================================== */
.btn-new-workspace,
.btn-edit-workspace,
.btn-primary {
	background: var(--primary) !important;
	color: var(--primary-text-color) !important;
	font-weight: 600 !important;
	border-radius: 6px !important;
	padding: 6px 14px !important;
	box-shadow: 0 4px 14px rgba(0, 0, 0, 0.06) !important;
	transition: 0.2s ease all;
}

.btn-new-workspace:hover,
.btn-edit-workspace:hover {
	transform: translateY(-3px);
	box-shadow: 0 6px 20px rgba(0, 0, 0, 0.1) !important;
}


/* =====================================================
   STANDARD FILTERS
===================================================== */
.standard-filter-section .form-control,
.standard-filter-section input[type="text"],
{
	background: #fff !important;
	border: 1px solid #000 !important;
	color: #222 !important;
	border-radius: 7px !important;
	padding: 6px 12px !important;
	transition: 0.2s;
}

/* .page-form {
	background: var(--secondary) !important;
	color: #222 !important;
} */

.standard-filter-section .form-control:focus {
	border-color: var(--primary) !important;
	box-shadow: 0 0 0 2px var(--primary);
}

.standard-filter-section .form-group {
	margin-bottom: 12px;
}


/* =====================================================
   LIST VIEW ROWS
===================================================== */
.list-row-container .list-row {
	background-color: transparent;
	border-top: 1px solid var(--primary);
}

.list-row-container:nth-of-type(even) .list-row {
	background-color: var(--secondary);
}

.list-row-container:hover .list-row {
	background-color: var(--primary);
}


/* =====================================================
   DATATABLE
===================================================== */
.datatable .dt-row:not(.dt-row-header):nth-of-type(odd) .dt-cell {
	background-color: var(--secondary) !important;
}


/* =====================================================
   EDITOR & TIMELINE
===================================================== */
.ce-header .h4 {
	color: var(--secondary-text-color-light) !important;
}

.new-timeline .activity-title,
.new-timeline .timeline-actions {
	background-color: transparent !important;
}


/* =====================================================
   FORM & INPUTS
===================================================== */
.form-page {
	background: var(--secondary) !important;
	border-radius: 14px !important;
}

.control-input:not(:has(button)),
.like-disabled-input,
.form-in-grid {
	border-radius: var(--border-radius) !important ;
	border: 1px solid var(--border-color) !important ;
	transition: 0.2s;
}


/* =====================================================
   HIDE ELEMENTS
===================================================== */
.file-preview div.flex.config-area label.frappe-checkbox,
.comment-wrapper,
.comment-box {
	display: none !important;
}
